const items = $input.all();
const lines = items.map(function (item) {
  const j = item.json || {};
  const from = j.From || "Unknown sender";
  const subject = j.Subject || "(no subject)";
  const snippet = j.snippet || "";
  return "- From: " + from + " | Subject: " + subject + " | " + snippet;
});
const emailsText = lines.length > 0 ? lines.join("\n") : "No new emails today.";
return [{ json: { emailsText: emailsText, emailCount: items.length } }];

const items = $input.all();
const lines = items.map(function (item) {
  const j = item.json || {};
  const summary = j.summary || "(untitled event)";
  const start = (j.start && (j.start.dateTime || j.start.date)) || "unknown time";
  const end = (j.end && (j.end.dateTime || j.end.date)) || "";
  return "- " + start + (end ? (" to " + end) : "") + ": " + summary;
});
const eventsText = lines.length > 0 ? lines.join("\n") : "No events scheduled today.";
return [{ json: { eventsText: eventsText, eventCount: items.length } }];

